mapper.select:
SELECT id, group_id, label, display_order, created_at, updated_at
FROM report_item_subtitles
WHERE id = #{id}

mapper.update:
UPDATE report_item_subtitles
SET label = #{label}
WHERE id = #{id}

mapper.select:
SELECT COALESCE(MAX(display_order), -1)
FROM report_item_subtitles
WHERE group_id = #{groupId}
